// Eingabe prüfen, bevor ein (kostenpflichtiger) LLM-Aufruf passiert.
const body = $json.body;
const errors = [];

if (!body || typeof body !== 'object' || Array.isArray(body)) {
  errors.push('Body muss ein JSON-Objekt sein.');
}
const message = typeof body?.message === 'string' ? body.message.trim() : '';
const app = typeof body?.app === 'string' ? body.app.trim() : '';
const email = typeof body?.user_email === 'string' && body.user_email.includes('@')
  ? body.user_email.trim()
  : null;

if (!message) errors.push('Feld "message" fehlt oder ist leer.');
if (message.length > 10000) errors.push('Feld "message" ist länger als 10000 Zeichen.');
if (!app) errors.push('Feld "app" fehlt oder ist leer.');

return [{ json: { ok: errors.length === 0, errors, app: app.slice(0, 100), user_email: email, message } }];

// Claude-Antwort sicher auslesen. Structured Outputs garantieren schema-konformes JSON,
// aber nur, wenn die Antwort vollständig ist. Abgefangen werden: Ablehnung (refusal),
// abgeschnittene Antwort (max_tokens), fehlender Text-Block, kaputtes JSON, falsche Werte.
const CATEGORIES = ['bug', 'feature_request', 'praise', 'question', 'other'];
const SENTIMENTS = ['positive', 'neutral', 'negative'];
const PRIORITIES = ['high', 'medium', 'low'];
const FALLBACK = {
  category: 'other',
  sentiment: 'neutral',
  priority: 'medium',
  summary: 'Klassifizierung fehlgeschlagen, bitte manuell prüfen.',
};

const input = $('validate_input').first().json;
const res = $json;
// Nicht content[0] nehmen: Vor dem Text kann ein thinking-Block stehen.
const textBlock = (res.content ?? []).find((b) => b.type === 'text');

let parsed = null;
let reason = null;
if (res.stop_reason === 'refusal') reason = 'refusal';
else if (res.stop_reason === 'max_tokens') reason = 'max_tokens';
else if (!textBlock) reason = 'no_text_block';
else {
  try {
    parsed = JSON.parse(textBlock.text);
  } catch (e) {
    reason = 'invalid_json';
  }
}

const c = parsed ?? FALLBACK;
const pick = (value, allowed, fallback) => {
  if (allowed.includes(value)) return value;
  reason = reason ?? 'schema_violation';
  return fallback;
};

return [{
  json: {
    category: pick(c.category, CATEGORIES, FALLBACK.category),
    sentiment: pick(c.sentiment, SENTIMENTS, FALLBACK.sentiment),
    priority: pick(c.priority, PRIORITIES, FALLBACK.priority),
    summary: typeof c.summary === 'string' && c.summary.trim() ? c.summary.trim().slice(0, 300) : FALLBACK.summary,
    parse_error: reason !== null,
    error_reason: reason,
    model: res.model ?? 'claude-haiku-5-5',
    input_tokens: res.usage?.input_tokens ?? null,
    output_tokens: res.usage?.output_tokens ?? null,
    original: input,
  },
}];

// Der Antwortentwurf ist ein Extra. Schlägt der Aufruf fehl (onError: continue),
// wird das Feedback trotzdem gespeichert, nur ohne Entwurf.
const classification = $('validate_classification').first().json;
const res = $json;
const textBlock = (res.content ?? []).find((b) => b.type === 'text');
const draft = res.stop_reason === 'end_turn' && textBlock ? textBlock.text.trim() : null;

return [{ json: { ...classification, draft_reply: draft } }];
